import { env } from 'node:process';
import { resolveDeployedResources } from '../../utils/blueprints/resolve-deployed-resources.js';
import { niceId } from '../../utils/display/presenters.js';
import { CODE_OPERATION_UNCONFIRMED, EXIT_OPERATION_UNCONFIRMED } from '../../utils/exit-codes.js';
import { styleText } from '../../utils/style-text.js';
import { isAssetResource, } from '../../utils/types.js';
import { stashAsset } from './assets.js';
import { updateStack } from './stacks.js';
import { waitForOperation } from './wait-for-operation.js';
const DEFAULT_ASSET_TIMEOUT = 180;
const assetTimeoutS = Number(process.env.SANITY_ASSET_TIMEOUT) || DEFAULT_ASSET_TIMEOUT;
const assetTimeoutMs = assetTimeoutS * 1000;
const warnTimeoutMs = assetTimeoutMs / 3;
export async function preDeploy(options) {
    const { resources, stackId, auth, blueprintFileDir, installer, log } = options;
    const hasAssetResources = resources.some(isAssetResource);
    if (hasAssetResources) {
        let assetResources;
        if (env.SANITY_BLUEPRINTS_PRE_DEPLOY_ENABLED === 'true') {
            const preDeployStackResult = await preDeployStack(options);
            if (!preDeployStackResult.success) {
                return preDeployStackResult;
            }
            /** Look up resources from the back-end and attach the externalId if possible */
            const resolvedResources = await resolveDeployedResources({
                resources,
                stackId,
                auth,
                logger: log,
            });
            assetResources = resolvedResources.filter(isAssetResource);
        }
        else {
            assetResources = resources.filter(isAssetResource);
        }
        log('Processing assets...');
        for (const resource of assetResources) {
            const preDeployResult = await preDeployResource(resource, {
                auth,
                blueprintFileDir,
                installer,
                log,
            });
            if (!preDeployResult.success)
                return preDeployResult;
            const idx = resources.findIndex((r) => r.name === resource.name);
            if (idx === -1)
                throw new Error('Unable to update resource asset');
            resources[idx] = preDeployResult.resource;
        }
    }
    return { success: true };
}
async function preDeployStack(options) {
    const { scopeType, scopeId, stackId, stackName, resources, auth, log, bin, verbose } = options;
    const spinner = log.ora('Starting pre-deploy...').start();
    const stackMutation = {
        scopeType,
        scopeId,
        name: stackName,
        preDeploy: true,
        document: { resources },
    };
    const { ok: deployOk, stack, error: deployError, } = await updateStack({ stackId, stackMutation, auth, logger: log });
    if (!deployOk) {
        spinner.fail(`${styleText('red', 'Failed')} to complete Stack pre-deployment`);
        return {
            success: false,
            error: deployError || 'Failed to complete Stack pre-deployment',
            suggestions: [
                `Run \`npx ${bin} blueprints plan\` to preview changes before deploying.`,
                `Run \`npx ${bin} blueprints doctor\` to check your configuration.`,
            ],
        };
    }
    spinner.stop().clear();
    log(styleText('dim', 'Stack deployment progress:'));
    log('');
    const outcome = await waitForOperation({
        stackId,
        operationId: stack.operationId,
        auth,
        log,
        bin,
        verbose,
        progressNoun: 'pre-deployment',
    });
    if (outcome.type === 'completed') {
        log(styleText(['bold', 'green'], 'Stack pre-deployment completed!'));
    }
    else if (outcome.type === 'unconfirmed') {
        return {
            success: false,
            error: `Stack pre-deployment was accepted but completion could not be confirmed${outcome.error ? ` (${outcome.error})` : ''}.`,
            code: CODE_OPERATION_UNCONFIRMED,
            exitCode: EXIT_OPERATION_UNCONFIRMED,
            suggestions: [
                'The pre-deployment may or may not have finished on Sanity servers.',
                `Run \`npx ${bin} blueprints info\` to check status.`,
                `Run \`npx ${bin} blueprints logs --watch\` to keep streaming logs.`,
            ],
        };
    }
    else {
        return {
            success: false,
            error: 'Stack pre-deployment failed',
            suggestions: [
                ...outcome.logHints,
                'Review the pre-deployment output above for error details.',
                `Run \`npx ${bin} blueprints logs --verbose\` for more context.`,
                `Run \`npx ${bin} blueprints plan\` to identify issues with your Blueprint.`,
            ],
        };
    }
    return { success: true };
}
async function preDeployResource(resource, options) {
    const { auth, blueprintFileDir, installer, log } = options;
    const fnSpinner = log.ora({ text: `Processing ${resource.name}...`, prefixText: ' ' }).start();
    const warnTimer = setTimeout(() => {
        fnSpinner.text = `Still processing ${resource.name}, this can take a moment...`;
    }, warnTimeoutMs);
    let assetTimeoutTimer;
    let result;
    try {
        result = await Promise.race([
            stashAsset({ resource, blueprintFileDir, auth, logger: log, installer }),
            new Promise((_, reject) => {
                assetTimeoutTimer = setTimeout(() => {
                    reject(new Error(`Processing ${resource.name} timed out after ${assetTimeoutS}s`));
                }, assetTimeoutMs);
            }),
        ]);
    }
    catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        fnSpinner.fail(msg);
        return { success: false, error: msg };
    }
    finally {
        clearTimeout(warnTimer);
        clearTimeout(assetTimeoutTimer);
    }
    if (result.success && result.assetId) {
        const updatedResource = { ...resource, src: result.assetId };
        fnSpinner.succeed(`${updatedResource.name} ${niceId(result.assetId)}`);
        log(`   Source: ${updatedResource.src}`);
        if (result.hash) {
            if (result.hash.length > 24) {
                log.verbose(`   Hash: ${result.hash.slice(0, 8)}...${result.hash.slice(-12)}`);
            }
            else {
                log.verbose(`   Hash: ${result.hash}`);
            }
        }
        if (result.exists)
            log.verbose('   Asset unchanged');
        return { success: true, resource: updatedResource };
    }
    const errorMsg = `Failed uploading ${resource.name} asset, deploy has stopped`;
    fnSpinner.fail(errorMsg);
    return { success: false, error: result.error || 'Failed to process asset' };
}
